"""Public English update from synthetic test receipts; never biometric exports."""
import datetime,html,json,re
from pathlib import Path
from final_verify import runtime_signature

ROOT=Path(__file__).parent
LIVE=Path('/mnt/nvme/robo-speaker-studies/speaker-live-results')

def read(path):
    return json.loads(path.read_text()) if path.exists() else {}

def main():
    signature=runtime_signature()
    visual=read(LIVE/'proactive-visual-live.json');audio=read(LIVE/'proactive-live.json')
    ui=read(ROOT/'logs/reliability-ui-checks.json');browser=read(ROOT/'logs/multimodal-browser-checks.json')
    gaze=read(ROOT/'logs/gaze-rendering-checks.json');unit=read(ROOT/'logs/unit-checks.json')
    mic=read(ROOT/'logs/browser-capture-desk.json');gate=read(ROOT/'logs/multimodal-live-checks.json')
    def current(receipt,count):
        return bool(receipt.get('passed') and len(receipt.get('cases',[]))>=count and receipt.get('runtime_source_sha256')==signature)
    escape=lambda v:html.escape(str(v))
    def table(headers,rows):
        return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    def status(ok):return 'PASS' if ok else 'PENDING / NOT VERIFIED ON THIS SOURCE'
    checks=[('Camera/follow defaults, independent voice/face cards, mobile layout',status(ui.get('passed')),'Real Chromium; fake camera and deterministic landmark behavior'),
        ('Current visual-assisted proactive interruption + 3 negative controls',status(current(visual,4)),'Real microphone-packet ASR, Luna rule tools and TTS; synthetic face/activity confirmations'),
        ('Current audio-only proactive interruption + 3 negative controls',status(current(audio,4)),'Real ASR, Luna tools, acoustic verification and TTS; no camera rescue'),
        ('Real browser microphone → ASR → reply audio, both filter modes',status(mic.get('passed')),'Synthetic fake-device audio; not a physical microphone'),
        ('Visible/offscreen/static/overlap/filter-off/camera-off/greeting checks',status(current(gate,8)),'Eight real ASR/TTS integration conditions with synthetic visual observations'),
        ('Real CPU face models, consent and multi-face behavior',status(browser.get('passed')),'MediaPipe and face-api workers; public test imagery; no human accuracy claim'),
        ('Gaze, keyboard calibration and CPU rendering regression',status(gaze.get('passed')),'Real UI/renderer, synthetic positions and fake capture'),
        ('Offline contracts',status(unit.get('passed')),str(unit.get('tests',0))+' tests; no network or physical devices')]
    out='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby · reliability and people gallery</title><style>body{font:16px/1.6 system-ui;max-width:1120px;margin:auto;padding:24px;background:#f8f7f3;color:#25343c}h1,h2{line-height:1.2}section{background:white;border-radius:16px;padding:20px;margin:20px 0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;background:white}td,th{padding:10px;border:1px solid #ddd;text-align:left;vertical-align:top}pre{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#306a74}</style><nav><a href="/desk-robot/">Open Robby</a> · <a href="/static/worklog.html">Task log</a> · <a href="/static/multimodal-report.html">Multimodal report</a> · <a href="/downloads/robby-source.zip">Source ZIP</a></nav><h1>Interruption reliability, camera following and people</h1>'''
    out+='<p>Updated '+escape(datetime.datetime.now(datetime.timezone.utc).isoformat())+'. The tests below use public synthetic voices and fake/synthetic visual input. They do not establish physical-room identity accuracy.</p>'
    out+=table(['Check','Result','Scope'],checks)
    out+='<section><h2>What changed</h2><ol><li><strong>Retry instead of silently hanging.</strong> An ASR partial is consumed only after voice/visual verification and actual interjection admission. Rejected/busy attempts are retried, including unchanged words. Fresh speech is required; the bounded ASR age is four seconds. The visible status explains missing words, uncertain voice or visual gating.</li><li><strong>Independent corroboration, not indiscriminate lower thresholds.</strong> Audio-only strong teacher, fast/long and sequential checks remain. Four strong complete checks spanning at least 1.8 seconds can recover an initially weak voice. A separately linked, freshly recognized and visibly speaking face permits a corroborated route, still requiring teacher cosine, initial/mean complete-context evidence, fast and long same-person cues and rival margins. Short, incomplete priming audio does not contaminate this route’s complete-context average. The normal full-turn threshold remains 0.32.</li><li><strong>Short replies can be ready before the trigger.</strong> A four-clip session-RAM cache opportunistically pre-renders the exact agreed brief reply using the shared TTS model while idle. Foreground speech cancels warming. Truncated/overlong audio is not cached; a miss uses ordinary streaming TTS.</li><li><strong>No duplicate response to the interrupted tail.</strong> A later ASR fragment inside the already-consumed monologue is suppressed even when it no longer includes the topic word. Explicit stop/cancellation/new-request commands and genuinely later turns remain eligible.</li><li><strong>Camera and gaze controls are back at the top.</strong> Camera auto-start and Follow my position default ON, subject to browser permission. Intentional opt-out persists. A stable primary face is followed even with several visible faces; a confidently active face can take over. Centre &amp; follow resets manual inspection.</li><li><strong>Inspectable people, not hidden biometric guesses.</strong> The always-visible people panel separates the stored enrollment crop, current camera crop, voice state and face state. Existing profiles with no enrollment photo say “No reference image”. Images stay local. Saving remains OFF without explicit permission from everyone involved.</li></ol></section>'
    rows=[];breakdown=[]
    for label,receipt in [('Visible known face (synthetic signal)',visual),('Audio only',audio)]:
        for case in receipt.get('cases',[]):
            begin=case.get('user_start_s',0)
            def delta(key):return round(case[key]-begin,3) if case.get(key) is not None else '—'
            rows.append((label,case.get('condition'),case.get('passed'),case.get('interrupted'),delta('decision_at_s'),delta('first_new_audio_s'),case.get('spoken_before_user_end'),receipt.get('runtime_source_sha256')==signature))
            if case.get('condition')!='positive' or not case.get('interrupted'):continue
            mentions=[e['at_s'] for e in case.get('events',[]) if e.get('type')=='asr_preview' and e.get('source')=='native_asr' and e.get('phase')=='probe' and e.get('at_s',0)>=begin and re.search(r'\bbanan',e.get('text',''),re.I)]
            replies=[e for e in case.get('events',[]) if e.get('type')=='reply' and e.get('phase')=='probe']
            first=min(mentions) if mentions else None
            breakdown.append((label,round(first-begin,3) if first else '—',round(case['decision_at_s']-first,3) if first else '—',round(case['first_new_audio_s']-case['decision_at_s'],3) if case.get('first_new_audio_s') else '—',replies[0].get('timing',{}).get('interjection_cache_hit') if replies else None))
    out+='<section><h2>Measured live interruption</h2><p>Seconds from probe clip start, including initial quiet audio. The probe continues while Robby speaks. Setup uses actual spoken ASR and Luna tool calls, not a test-only installed rule. No hidden retry is counted as a pass.</p>'
    out+=table(['Route','Condition','Case passed','Interrupted','Decision (s)','First audio (s)','Before user ended','Current source'],rows)
    out+='<h3>Where the positive-case time goes</h3>'+table(['Route','First banana ASR (s)','Then identity/controller (s)','Then TTS + virtual DAC (s)','Cache hit'],breakdown)
    out+='<p>The virtual playback device buffers 240 ms; simulated echo reaches the microphone 120 ms later at gain 0.05. The first preparatory audio-only run had about 8.18 seconds to decision and 8.42 seconds to virtual audio, despite a 2-ms cached TTS onset. A later visual pilot exposed incomplete early context contaminating cumulative evidence and a duplicate keyword-free tail response; it was retained as a failure and repaired before the current tests. Source hashes prevent edited-during-test receipts from becoming current-source passes. This is not a guarantee of subsecond physical response.</p></section>'
    out+='<section><h2>Try it</h2><ol><li>Reload the demo. Allow the camera, then press Start talking and allow the microphone. If you previously chose Camera off, enable Start camera automatically or press Centre &amp; follow me.</li><li>Introduce yourself while clearly visible: “Hey Robby, ich bin Christoph.” The People panel should show a reference/current image and separate voice/face information.</li><li>Agree the game: “Wenn ich über Bananen rede, unterbrich mich und sag Stopp, stopp.” Check the installed rule in Agreed rules &amp; interruption details, not just the spoken acknowledgment.</li><li>Speak about the topic without waiting for silence. The status shows any remaining gate. Stop reply always cancels manually; recognized spoken stop commands retain their existing acoustic verification.</li><li>Recognition &amp; privacy settings contains voice sensitivity, offscreen filtering and optional consented profile storage. Advanced contains rendering/eye-contact diagnostics; microphone diagnostics are collapsible under the toolbar.</li></ol></section>'
    models=browser.get('real_models',{})
    out+='<section><h2>CPU cost, privacy and remaining limits</h2><p>No extra server GPU model or redundant camera pipeline was added. The existing MediaPipe CPU/WASM landmark worker targets 10 FPS for up to four faces. The lazy face-api.js worker produces 128-D descriptors; warm per-crop timings in this host’s latest browser test were '+escape([round(x['ms'],1) for x in models.get('embedding',[])][1:])+ ' ms, not per-video-frame costs. Local thumbnails refresh at most once per second and cards at a bounded rate. Camera permission cannot be bypassed.</p><p>Reference images are the real local eye-aligned enrollment crops, not generated portraits. Default memory is session-only. Opt-in local storage is unencrypted and requires everyone’s permission; withdrawing consent removes saved profiles, and Forget all clears session identities. No private audio, photos or enrolled voiceprints are included in this report or source archive.</p><p>Face and speaker similarity are approximate cues, not authentication. Static open mouths, offscreen sound, overlap and unknown voice controls are tested, but chewing, occlusion, playback attacks, physical A/V drift and real human false-acceptance rates remain unmeasured. Historical generic semantic-rule and very short spoken-stop failures remain visible in the task log. The ordinary 0.32 post-pause voice gate is deliberately permissive and is not a guarantee against every timbre-confusable background speaker. A missing camera explicitly falls back to audio-only behavior; a camera ON with no uniquely speaking face abstains by default.</p></section>'
    out+='<section><h2>Changed files and reproduction</h2><p>Live logic: <code>live_decisions.py, interaction_policy.py, speaker_session.py, visual_identity.py, server.py, tts_bridge.py</code>. UI/gallery: <code>static/index.html, static/ui.js, static/playground-layout.js, static/people-view.js, static/multimodal-ui.js, static/visual-speakers.js, static/controls.css</code>. Browser/live harnesses, regression tests, README and the report/task-log builders were updated additively. No model weights or private recordings are included in the source export.</p><pre>python run_unit_checks.py\nuv run --no-project --with playwright --python /path/to/python browser_reliability_checks.py\nuv run --no-project --with playwright --python /path/to/python browser_multimodal_checks.py\nuv run --no-project --with playwright --python /path/to/python browser_gaze_checks.py\npython -m speaker_live.proactive_test --visual\npython -m speaker_live.proactive_test\npython multimodal_live_checks.py\nuv run --no-project --with playwright --python /path/to/python browser_mic_checks.py --url https://YOUR-HOST/desk-robot/\npython build_reliability_report.py</pre><p>Run ASR/TTS live tests sequentially: the pilot has one real-time slot. Browser-only behavioral tests use synthetic landmarks; CPU model tests use public imagery separately. Runtime source SHA-256: <code>'+escape(signature)+'</code>.</p></section></html>'
    (ROOT/'static/reliability-update.html').write_text(out)
    print(json.dumps({'report':'static/reliability-update.html','visual_current_pass':current(visual,4),'audio_current_pass':current(audio,4),'gate_current_pass':current(gate,8),'ui_pass':ui.get('passed')}))

if __name__=='__main__':main()
